Here is the commit message:
media: ccs: Avoid possible division by zero

Calculating maximum M for scaler configuration involves dividing by
MIN_X_OUTPUT_SIZE limit register's value. Albeit the value is presumably
non-zero, the driver was missing the check it in fact was. Fix this.

Reported-by: Josh Poimboeuf <jpoimboe@kernel.org>
Closes: https://lore.kernel.org/all/ahukd6b3wonye3zgtptvwzvrxldcruazs2exfvll6etjhmcxyj@vq3eh6pd375b/
Fixes: ccfc97bdb5ae ("[media] smiapp: Add driver")
Cc: stable@vger.kernel.org # for 5.15 and later
Signed-off-by: Sakari Ailus <sakari.ailus@linux.intel.com>
Reviewed-by: Nathan Chancellor <nathan@kernel.org>
Tested-by: Nathan Chancellor <nathan@kernel.org> # build
Signed-off-by: Hans Verkuil <hverkuil+cisco@kernel.org>

Here is the root cause:
The driver performs division by the MIN_X_OUTPUT_SIZE limit register value without checking for zero, which can lead to a division by zero if the register reads as zero.

Here is the patch:
  */
 static void ccs_set_compose_scaler(struct v4l2_subdev *subdev,
 				   struct v4l2_subdev_state *sd_state,
 				   struct v4l2_subdev_selection *sel,
 				   struct v4l2_rect **crops,
 				   struct v4l2_rect *comp)
 {
 	struct i2c_client *client = v4l2_get_subdevdata(subdev);
 	struct ccs_sensor *sensor = to_ccs_sensor(subdev);
 	u32 min, max, a, b, max_m;
 	u32 scale_m = CCS_LIM(sensor, SCALER_N_MIN);
 	int mode = CCS_SCALING_MODE_HORIZONTAL;
 	u32 try[4];
 	u32 ntry = 0;
 	unsigned int i;
 	int best = INT_MIN;

 	sel->r.width = min_t(unsigned int, sel->r.width,
 			     crops[CCS_PAD_SINK]->width);
 	sel->r.height = min_t(unsigned int, sel->r.height,
 			      crops[CCS_PAD_SINK]->height);

 	a = crops[CCS_PAD_SINK]->width
 		* CCS_LIM(sensor, SCALER_N_MIN) / sel->r.width;
 	b = crops[CCS_PAD_SINK]->height
 		* CCS_LIM(sensor, SCALER_N_MIN) / sel->r.height;
 	max_m = crops[CCS_PAD_SINK]->width
 		* CCS_LIM(sensor, SCALER_N_MIN)
-		/ CCS_LIM(sensor, MIN_X_OUTPUT_SIZE);
+		/ (CCS_LIM(sensor, MIN_X_OUTPUT_SIZE) ?: 1);

 	a = clamp(a, CCS_LIM(sensor, SCALER_M_MIN),
 		  CCS_LIM(sensor, SCALER_M_MAX));
 	b = clamp(b, CCS_LIM(sensor, SCALER_M_MIN),
 		  CCS_LIM(sensor, SCALER_M_MAX));
 	max_m = clamp(max_m, CCS_LIM(sensor, SCALER_M_MIN),
 		      CCS_LIM(sensor, SCALER_M_MAX));

 	dev_dbg(&client->dev, "scaling: a %u b %u max_m %u\n", a, b, max_m);

 	min = min(max_m, min(a, b));
 	max = min(max_m, max(a, b));

 	try[ntry] = min;
 	ntry++;
 	if (min != max) {
 		try[ntry] = max;
 		ntry++;
 	}
 	if (max != max_m) {
 		try[ntry] = min + 1;
 		ntry++;
 		if (min != max) {
 			try[ntry] = max + 1;
 			ntry++;
 		}
 	}

 	for (i = 0; i < ntry; i++) {
 		int this = scaling_goodness(
 			subdev,
 			crops[CCS_PAD_SINK]->width
 			/ try[i] * CCS_LIM(sensor, SCALER_N_MIN),
 			sel->r.width,
 			crops[CCS_PAD_SINK]->height,
 			sel->r.height,
 			sel->flags);

 		dev_dbg(&client->dev, "trying factor %u (%u)\n", try[i], i);

 		if (this > best) {
 			scale_m = try[i];
 			mode = CCS_SCALING_MODE_HORIZONTAL;
 			best = this;
 		}

 		if (CCS_LIM(sensor, SCALING_CAPABILITY)
 		    == CCS_SCALING_CAPABILITY_HORIZONTAL)
 			continue;

 		this = scaling_goodness(
 			subdev, crops[CCS_PAD_SINK]->width
 			/ try[i]
 			* CCS_LIM(sensor, SCALER_N_MIN),
 			sel->r.width,
 			crops[CCS_PAD_SINK]->height
 			/ try[i]
 			* CCS_LIM(sensor, SCALER_N_MIN),
 			sel->r.height,
 			sel->flags);

 		if (this > best) {
 			scale_m = try[i];
 			mode = SMIAPP_SCALING_MODE_BOTH;
 			best = this;
 		}
 	}

 	sel->r.width =
 		(crops[CCS_PAD_SINK]->width
 		 / scale_m
 		 * CCS_LIM(sensor, SCALER_N_MIN)) & ~1;
 	if (mode == SMIAPP_SCALING_MODE_BOTH)
 		sel->r.height =
 			(crops[CCS_PAD_SINK]->height
 			 / scale_m
 			 * CCS_LIM(sensor, SCALER_N_MIN))
 			& ~1;
 	else
 		sel->r.height = crops[CCS_PAD_SINK]->height;

 	if (sel->which == V4L2_SUBDEV_FORMAT_ACTIVE) {
 		sensor->scale_m = scale_m;
 		sensor->scaling_mode = mode;
 	}
 }
 /* We're only called on source pads. This function sets scaling. */


